    for (int pass = 0; pass < 2; pass++) {
        st.clear();
        for (int i = 0; i < n; i++) {
            long long v = pass == 0 ? a[i] : a[n - 1 - i];
            while (!st.empty() && (pass == 0 ? a[st.back()] : a[n - 1 - st.back()]) <= v) st.pop_back();
            answer += i - (st.empty() ? -1 : st.back());
            st.push_back(i);
        }
    }
    // Subtract subarrays where both ends are the maximum (counted twice).
    vector<pair<long long, long long>> groups;
    long long both = 0;
    for (long long v : a) {
        while (!groups.empty() && groups.back().first < v) groups.pop_back();
        if (!groups.empty() && groups.back().first == v) { groups.back().second++; both += groups.back().second; }
        else { groups.push_back({v, 1}); both++; }
    }
    cout << answer - both << "\n";
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long answer = 0;
        int[] st = new int[n];
        // Subarrays where the right end is a maximum, then (mirrored) where the left end is.
        for (int pass = 0; pass < 2; pass++) {
            int top = 0;
            for (int i = 0; i < n; i++) {
                long v = pass == 0 ? a[i] : a[n - 1 - i];
                while (top > 0 && (pass == 0 ? a[st[top - 1]] : a[n - 1 - st[top - 1]]) <= v) top--;
                answer += i - (top > 0 ? st[top - 1] : -1);
                st[top++] = i;
            }
        }
        // Subtract subarrays where both ends are the maximum (counted twice).
        long[] gv = new long[n], gc = new long[n];
        int g = 0;
        long both = 0;
        for (long v : a) {
            while (g > 0 && gv[g - 1] < v) g--;
            if (g > 0 && gv[g - 1] == v) {
                gc[g - 1]++;
                both += gc[g - 1];
            } else {
                gv[g] = v;
                gc[g++] = 1;
                both++;
            }
        }
        System.out.println(answer - both);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	answer := int64(0)
	st := make([]int, 0, n)
	// Subarrays where the right end is a maximum, then (mirrored) where the left end is.
	for pass := 0; pass < 2; pass++ {
		val := func(i int) int64 {
			if pass == 0 {
				return a[i]
			}
			return a[n-1-i]
		}
		st = st[:0]
		for i := 0; i < n; i++ {
			v := val(i)
			for len(st) > 0 && val(st[len(st)-1]) <= v {
				st = st[:len(st)-1]
			}
			prev := -1
			if len(st) > 0 {
				prev = st[len(st)-1]
			}
			answer += int64(i - prev)
			st = append(st, i)
		}
	}
	// Subtract subarrays where both ends are the maximum (counted twice).
	type group struct{ value, count int64 }
	groups := make([]group, 0, n)
	both := int64(0)
	for _, v := range a {
		for len(groups) > 0 && groups[len(groups)-1].value < v {
			groups = groups[:len(groups)-1]
		}
		if len(groups) > 0 && groups[len(groups)-1].value == v {
			groups[len(groups)-1].count++
			both += groups[len(groups)-1].count
		} else {
			groups = append(groups, group{v, 1})
			both++
		}
	}
	fmt.Println(answer - both)
}
